@page "/book-appointment"
@rendermode InteractiveServer
@using sv_9a4e5b2aaf0a4e40920fbda4f6a82bd3.Services
@inject IAppointmentService AppointmentService

<PageTitle>Book Appointment</PageTitle>

<h1>Book an Appointment</h1>

<EditForm EditContext="editContext" OnSubmit="HandleSubmit" FormName="book-appointment">
    <DataAnnotationsValidator />
    <CustomValidator @ref="customValidator" />

    <fieldset>
        <legend>Patient Information</legend>

        <div class="mb-3">
            <label class="form-label">Patient Name</label>
            <InputText class="form-control" @bind-Value="model.PatientName" />
            <ValidationMessage For="() => model.PatientName" />
        </div>

        <div class="mb-3">
            <label class="form-label">Email</label>
            <InputText class="form-control" @bind-Value="model.Email" />
            <ValidationMessage For="() => model.Email" />
        </div>

        <div class="mb-3">
            <label class="form-label">Phone</label>
            <InputText class="form-control" @bind-Value="model.Phone" />
            <ValidationMessage For="() => model.Phone" />
        </div>

        <div class="mb-3">
            <label class="form-label">Insurance Provider</label>
            <InputSelect class="form-select" @bind-Value="model.InsuranceProvider">
                <option value="">-- Select --</option>
                <option value="Aetna">Aetna</option>
                <option value="BlueCross">BlueCross</option>
                <option value="Cigna">Cigna</option>
                <option value="UnitedHealth">UnitedHealth</option>
                <option value="None">None</option>
            </InputSelect>
            <ValidationMessage For="() => model.InsuranceProvider" />
        </div>

        @if (!showStep2)
        {
            <button type="button" class="btn btn-primary" @onclick="ProceedToStep2">
                Next: Choose Appointment
            </button>
        }
    </fieldset>

    @if (showStep2)
    {
        <fieldset class="mt-4">
            <legend>Appointment Details</legend>

            <div class="mb-3">
                <label class="form-label">Preferred Doctor</label>
                <InputSelect class="form-select" @bind-Value="model.Doctor" @bind:after="OnDoctorOrDateChanged">
                    <option value="">-- Select --</option>
                    @foreach (var doctor in doctors)
                    {
                        <option value="@doctor">@doctor</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => model.Doctor" />
            </div>

            <div class="mb-3">
                <label class="form-label">Date</label>
                <InputDate class="form-control" @bind-Value="model.Date" @bind:after="OnDoctorOrDateChanged" />
                <ValidationMessage For="() => model.Date" />
            </div>

            <div class="mb-3">
                <label class="form-label">Time Slot</label>
                <InputSelect class="form-select" @bind-Value="model.TimeSlot" disabled="@(timeSlots.Count == 0)">
                    <option value="">-- Select --</option>
                    @foreach (var slot in timeSlots)
                    {
                        <option value="@slot">@slot</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => model.TimeSlot" />
            </div>

            <div class="mb-3">
                <label class="form-label">Reason for Visit</label>
                <InputTextArea class="form-control" @bind-Value="model.Reason" rows="3" />
                <ValidationMessage For="() => model.Reason" />
            </div>

            <button type="button" class="btn btn-secondary me-2" @onclick="BackToStep1">
                Back
            </button>
            <button type="button" class="btn btn-info me-2" @onclick="CheckAvailability" disabled="@isChecking">
                @(isChecking ? "Checking..." : "Check Availability")
            </button>
            <button type="submit" class="btn btn-primary" disabled="@(!availabilityConfirmed || isSubmitting)">
                @(isSubmitting ? "Booking..." : "Book Appointment")
            </button>
        </fieldset>

        @if (availabilityConfirmed)
        {
            <div class="alert alert-success mt-3" role="alert">
                Slot is available! Click <strong>Book Appointment</strong> to confirm.
            </div>
        }
    }
</EditForm>

@if (bookingConfirmed)
{
    <div class="alert alert-success mt-4" role="alert">
        <h4>Appointment Booked!</h4>
        <p>Your appointment with <strong>@model.Doctor</strong> on
           <strong>@model.Date?.ToString("MMMM d, yyyy")</strong> at
           <strong>@model.TimeSlot</strong> has been confirmed.</p>
    </div>
}

@code {
    private EditContext editContext = null!;
    private AppointmentFormModel model = new();
    private CustomValidator? customValidator;

    private bool showStep2;
    private bool isChecking;
    private bool isSubmitting;
    private bool availabilityConfirmed;
    private bool bookingConfirmed;

    private List<string> doctors = [];
    private List<string> timeSlots = [];

    // Step 1 fields for partial validation
    private static readonly string[] Step1Fields =
        [nameof(AppointmentFormModel.PatientName), nameof(AppointmentFormModel.Email),
         nameof(AppointmentFormModel.Phone), nameof(AppointmentFormModel.InsuranceProvider)];

    protected override async Task OnInitializedAsync()
    {
        editContext = new EditContext(model);
        doctors = await AppointmentService.GetDoctorsAsync();
    }

    private void ProceedToStep2()
    {
        // Validate only step 1 fields
        editContext.Validate();
        var hasStep1Errors = Step1Fields.Any(f =>
            editContext.GetValidationMessages(editContext.Field(f)).Any());

        if (!hasStep1Errors)
        {
            showStep2 = true;
        }
    }

    private void BackToStep1()
    {
        showStep2 = false;
        availabilityConfirmed = false;
    }

    private async Task OnDoctorOrDateChanged()
    {
        availabilityConfirmed = false;
        model.TimeSlot = null;
        timeSlots = [];

        if (!string.IsNullOrEmpty(model.Doctor) && model.Date.HasValue)
        {
            if (model.Date.Value <= DateOnly.FromDateTime(DateTime.Today))
            {
                return;
            }
            timeSlots = await AppointmentService.GetTimeSlotsAsync(model.Doctor, model.Date.Value);
        }
    }

    private async Task CheckAvailability()
    {
        customValidator?.ClearErrors();
        availabilityConfirmed = false;

        // Validate date is in the future
        if (model.Date.HasValue && model.Date.Value <= DateOnly.FromDateTime(DateTime.Today))
        {
            customValidator?.DisplayErrors(new Dictionary<string, List<string>>
            {
                [nameof(AppointmentFormModel.Date)] = ["Date must be in the future."]
            });
            return;
        }

        // Run full form validation
        var isValid = editContext.Validate();
        if (!isValid)
        {
            return;
        }

        isChecking = true;
        try
        {
            var errors = await AppointmentService.ValidatePatientAsync(
                model.Email!, model.InsuranceProvider!, model.Doctor!, model.TimeSlot!);

            if (errors.Count > 0)
            {
                customValidator?.DisplayErrors(errors);
            }
            else
            {
                availabilityConfirmed = true;
            }
        }
        finally
        {
            isChecking = false;
        }
    }

    private async Task HandleSubmit()
    {
        if (!availabilityConfirmed)
        {
            return;
        }

        isSubmitting = true;
        try
        {
            var request = new AppointmentRequest
            {
                PatientName = model.PatientName!,
                Email = model.Email!,
                Phone = model.Phone!,
                InsuranceProvider = model.InsuranceProvider!,
                Doctor = model.Doctor!,
                Date = model.Date!.Value,
                TimeSlot = model.TimeSlot!,
                Reason = model.Reason!
            };

            var success = await AppointmentService.SubmitAppointmentAsync(request);
            if (success)
            {
                bookingConfirmed = true;
            }
        }
        finally
        {
            isSubmitting = false;
        }
    }
}

